/* ChaCha20-Poly1305 against RFC 8439 and against a reference implementation.
 *
 * Section 2.8.2 and appendix A.5 pin down the whole construction: the
 * one-time key taken from the counter-zero block, the ciphertext starting at
 * counter one, and the padding of the two authenticated segments.  The
 * generated sweep then crosses every aad and message length near a Poly1305
 * block boundary and near a ChaCha20 keystream boundary, which is where the
 * segment machinery would go wrong if it were going to.  The last group is
 * the negative side: a tampered ciphertext, tag, aad or nonce must not
 * verify, and must not write any plaintext.
 *
 * Generated; do not edit by hand. */

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "Hacl.h"

static int failures = 0;

static uint8_t ct[512];
static uint8_t tag[16];
static uint8_t msg[512];

static void hexdump(const uint8_t *b, size_t n) {
  for (size_t i = 0; i < n; i++) printf("%02x", b[i]);
}

static void check(const char *name, const uint8_t *key, const uint8_t *nonce,
                  const uint8_t *aad, size_t aad_len,
                  const uint8_t *pt, size_t pt_len,
                  const uint8_t *ect, const uint8_t *etag) {
  memset(ct, 0xaa, sizeof ct);
  memset(tag, 0xaa, sizeof tag);
  Hacl_Chacha20Poly1305_encrypt(ct, tag, (uint8_t *)pt, pt_len,
                                    (uint8_t *)aad, aad_len,
                                    (uint8_t *)key, (uint8_t *)nonce);
  if (memcmp(ct, ect, pt_len) != 0 || memcmp(tag, etag, 16) != 0) {
    printf("FAIL %s (encrypt)\n  got      ", name);
    hexdump(ct, pt_len);
    printf(" / ");
    hexdump(tag, 16);
    printf("\n  expected ");
    hexdump(ect, pt_len);
    printf(" / ");
    hexdump(etag, 16);
    printf("\n");
    failures++;
    return;
  }

  memset(msg, 0x55, sizeof msg);
  bool ok = Hacl_Chacha20Poly1305_decrypt(msg, ct, pt_len, tag,
                                              (uint8_t *)aad, aad_len,
                                              (uint8_t *)key, (uint8_t *)nonce);
  if (!ok) {
    printf("FAIL %s (decrypt rejected a valid tag)\n", name);
    failures++;
    return;
  }
  if (memcmp(msg, pt, pt_len) != 0) {
    printf("FAIL %s (decrypt)\n  got      ", name);
    hexdump(msg, pt_len);
    printf("\n  expected ");
    hexdump(pt, pt_len);
    printf("\n");
    failures++;
  }
}

/* Every single-bit and single-byte perturbation of the inputs must be
 * rejected, and must leave the plaintext buffer alone. */
static void check_reject(const char *name, const uint8_t *key,
                         const uint8_t *nonce, const uint8_t *aad,
                         size_t aad_len, const uint8_t *pt, size_t pt_len) {
  static uint8_t bad_ct[512];
  static uint8_t bad_aad[512];
  uint8_t bad_key[32], bad_nonce[12], bad_tag[16];

  Hacl_Chacha20Poly1305_encrypt(ct, tag, (uint8_t *)pt, pt_len,
                                    (uint8_t *)aad, aad_len,
                                    (uint8_t *)key, (uint8_t *)nonce);

  for (int which = 0; which < 5; which++) {
    memcpy(bad_ct, ct, pt_len);
    memcpy(bad_aad, aad, aad_len);
    memcpy(bad_key, key, 32);
    memcpy(bad_nonce, nonce, 12);
    memcpy(bad_tag, tag, 16);
    switch (which) {
      case 0: if (pt_len == 0) continue; bad_ct[pt_len / 2] ^= 0x01; break;
      case 1: bad_tag[7] ^= 0x80; break;
      case 2: if (aad_len == 0) continue; bad_aad[aad_len - 1] ^= 0x40; break;
      case 3: bad_key[31] ^= 0x01; break;
      case 4: bad_nonce[0] ^= 0x01; break;
    }
    memset(msg, 0x55, sizeof msg);
    bool ok = Hacl_Chacha20Poly1305_decrypt(msg, bad_ct, pt_len, bad_tag,
                                                bad_aad, aad_len,
                                                bad_key, bad_nonce);
    if (ok) {
      printf("FAIL %s (tamper %d accepted)\n", name, which);
      failures++;
      continue;
    }
    for (size_t i = 0; i < pt_len; i++) {
      if (msg[i] != 0x55) {
        printf("FAIL %s (tamper %d wrote plaintext)\n", name, which);
        failures++;
        break;
      }
    }
  }
}

